/* Generates everything derived from the manifests:
     packages/contract/src/manifests/index.ts   the manifest registry
     packages/contract/manifest.json            the contract as JSON (PHP reads it)
     packages/svelte/src/lib/index.ts           the Svelte package's exports
   and (as they land) both runtimes' LLM stubs and the docs data.
   --check exits non-zero when a generated file is out of date. */
import { readdirSync, readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { renderStubs } from './stubs.ts';

const root = join(dirname(fileURLToPath(import.meta.url)), '../../..');
const check = process.argv.includes('--check');
const HEADER = 'Generated by packages/contract/scripts/generate.ts — do not edit.';
const stale: string[] = [];

function emit(path: string, content: string): void {
    const file = join(root, path);
    mkdirSync(dirname(file), { recursive: true });
    const current = existsSync(file) ? readFileSync(file, 'utf8') : null;
    if (current === content) return;
    if (check) stale.push(path);
    else writeFileSync(file, content);
}

/* -------- manifest registry ----------------------------------------------- */
const manifestDir = join(root, 'packages/contract/src/manifests');
const names = readdirSync(manifestDir).filter((f) => f.endsWith('.ts') && f !== 'index.ts').map((f) => f.slice(0, -3)).sort();
// A component named after a reserved word (switch) gets a suffix as an identifier.
const RESERVED = new Set(['switch', 'case', 'default', 'delete', 'new', 'import', 'export', 'class', 'function', 'return', 'var', 'let', 'const', 'in', 'do', 'if', 'for', 'while', 'with', 'try', 'catch', 'finally', 'throw', 'void', 'typeof', 'instanceof', 'this', 'super', 'extends', 'yield', 'enum', 'await', 'break', 'continue', 'debugger', 'else', 'null', 'true', 'false']);
const ident = (name: string) => {
    const id = name.replace(/[^a-zA-Z0-9]+(.)/g, (_, ch: string) => ch.toUpperCase()).replace(/^./, (ch) => ch.toLowerCase());
    return RESERVED.has(id) ? `${id}Manifest` : id;
};

emit('packages/contract/src/manifests/index.ts', [
    `/* ${HEADER} */`,
    `import type { ComponentManifest } from '../schema.ts';`,
    ...names.map((name) => `import ${ident(name)} from './${name}.ts';`),
    '',
    `export const manifests: ComponentManifest[] = [${names.map(ident).join(', ')}];`,
    '',
    'export const registry: Record<string, ComponentManifest> = Object.fromEntries(manifests.map((m) => [m.name, m]));',
    '',
].join('\n'));

const manifests = await Promise.all(names.map(async (name) => (await import(pathToFileURL(join(manifestDir, `${name}.ts`)).href)).default));
for (const manifest of manifests) {
    if (!names.includes(manifest.name)) throw new Error(`Manifest file and name differ: ${manifest.name}`);
}

/* -------- contract JSON ----------------------------------------------------- */
const json = manifests.map(({ examples, ...rest }) => ({ ...rest, examples: examples.map((e: { label: string }) => ({ label: e.label })) }));
emit('packages/contract/manifest.json', JSON.stringify({ comment: HEADER, components: json }, null, 2) + '\n');

/* -------- Svelte exports ---------------------------------------------------- */
// `Button` → components/Button.svelte; `Dropdown.Item` → components/Dropdown.Item.svelte,
// attached to the Dropdown export; a namespace with no root component (Section,
// Chart) is a plain object.
// A manifest whose Svelte component is not written yet is left out (with a
// warning), so the package stays importable while a component is under way;
// the Svelte contract test still fails until the file exists.
const svelteNames: string[] = manifests.map((m) => m.svelte).filter((path: string) => {
    const exists = existsSync(join(root, 'packages/svelte/src/lib/components', `${path}.svelte`));
    if (!exists) console.warn(`generate: no Svelte component for ${path} yet — not exported`);
    return exists;
});
const roots = new Map<string, string[]>();
for (const path of svelteNames) {
    const [head, ...tail] = path.split('.');
    if (!roots.has(head)) roots.set(head, []);
    if (tail.length) roots.get(head)!.push(tail.join('.'));
}
const local = (path: string) => `${path.replace(/\./g, '_')}_`;
const lines = [`/* ${HEADER} */`];
// A plain component is re-exported; a family is its root with members attached
// (or a plain object when there is no root), typed through `typeof` so the
// declarations can name every component.
for (const [head, members] of [...roots.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    if (!members.length) {
        lines.push(`export { default as ${head} } from './components/${head}.svelte';`);
        continue;
    }
    const hasRoot = svelteNames.includes(head);
    const names = members.sort();
    if (hasRoot) lines.push(`import ${local(head)} from './components/${head}.svelte';`);
    for (const member of names) lines.push(`import ${local(`${head}.${member}`)} from './components/${head}.${member}.svelte';`);
    const shape = `{ ${names.map((member) => `${member}: typeof ${local(`${head}.${member}`)}`).join('; ')} }`;
    const parts = names.map((member) => `${member}: ${local(`${head}.${member}`)}`).join(', ');
    lines.push(hasRoot
        ? `export const ${head}: typeof ${local(head)} & ${shape} = Object.assign(${local(head)}, { ${parts} });`
        : `export const ${head}: ${shape} = { ${parts} };`);
}
lines.push(
    `export { sigta, ensureRuntime } from './runtime/runtime.js';`,
    `export { leave, arrive } from './runtime/transitions.js';`,
    `export { setMessages, type Messages } from './runtime/messages.js';`,
    '',
);
emit('packages/svelte/src/lib/index.ts', lines.join('\n'));

/* -------- LLM context files ----------------------------------------------- */
// The Svelte edition ships what exists; the Livewire edition replaces the
// hand-written stubs only once every Blade component has a manifest, so a
// Livewire app never loses a component from its reference mid-migration.
const registry = Object.fromEntries(manifests.map((m) => [m.name, m]));
const svelteStubs = renderStubs(root, manifests, registry, 'svelte');
emit('packages/svelte/stubs/sigta-ui.md', svelteStubs.rules);
emit('packages/svelte/stubs/sigta-components.md', svelteStubs.components);

const bladeViews = (dir: string, prefix = ''): string[] => readdirSync(dir, { withFileTypes: true }).flatMap((entry) =>
    entry.isDirectory()
        ? bladeViews(join(dir, entry.name), `${prefix}${entry.name}.`)
        : entry.name.endsWith('.blade.php') ? [`${prefix}${entry.name.slice(0, -10)}`.replace(/\.index$/, '')] : []);
const missing = bladeViews(join(root, 'resources/views/components')).filter((name) => !registry[name]);
const livewireStubs = renderStubs(root, manifests, registry, 'livewire');
if (missing.length === 0) {
    emit('stubs/sigta-ui.md', livewireStubs.rules);
    emit('stubs/sigta-components.md', livewireStubs.components);
} else if (process.argv.includes('--preview')) {
    emit('packages/contract/.build/preview/sigta-ui.md', livewireStubs.rules);
    emit('packages/contract/.build/preview/sigta-components.md', livewireStubs.components);
}

if (check && stale.length) {
    console.error(`Generated files are out of date — run npm run generate:\n  ${stale.join('\n  ')}`);
    process.exit(1);
}
console.log(check ? 'generate: up to date' : `generate: ${manifests.length} manifests${missing.length ? ` (${missing.length} Blade components still without one; Livewire stubs left as they are)` : ''}`);
